def mat_pow_2x2(A, k):
    # A est [[a,b],[c,d]]
    def mul(X, Y):
        return [[X[0][0]*Y[0][0]+X[0][1]*Y[1][0], X[0][0]*Y[0][1]+X[0][1]*Y[1][1]],
                [X[1][0]*Y[0][0]+X[1][1]*Y[1][0], X[1][0]*Y[0][1]+X[1][1]*Y[1][1]]]
    result = [[1,0],[0,1]]
    base = A
    while k > 0:
        if k % 2 == 1:
            result = mul(result, base)
        base = mul(base, base)
        k //= 2
    return result
